import{_ as o,o as e,c as t,ag as r}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Korean-Philosophy/03. 원효의 화쟁.md","filePath":"philosophy/Korean-Philosophy/03. 원효의 화쟁.md"}'),l={name:"philosophy/Korean-Philosophy/03. 원효의 화쟁.md"};function i(n,a,s,h,p,_){return e(),t("div",null,[...a[0]||(a[0]=[r('<h2 id="공통적-의견" tabindex="-1">공통적 의견 <a class="header-anchor" href="#공통적-의견" aria-label="Permalink to &quot;공통적 의견&quot;">​</a></h2><p>언어와 사유가 세계를 분별하고 구분짓게 만듦. 언어는 있는 그대로를 가리고, 그것을 개념화시켜 본질을 보지 못하게 만듦.</p><h2 id="불교의-한반도-유입" tabindex="-1">불교의 한반도 유입 <a class="header-anchor" href="#불교의-한반도-유입" aria-label="Permalink to &quot;불교의 한반도 유입&quot;">​</a></h2><p><strong>고구려</strong></p><ol><li>현실을 중시하는 무속과 마찰 — 기복신앙과 불교 사이의 마찰</li><li>농업 기반의 사회제도와 충돌 — 노동집약적인 농업과 출가 중심의 불교 사이의 충돌<br> → 이후 신라와 일본으로 전파</li></ol><h2 id="원효의-삶과-문제의식" tabindex="-1">원효의 삶과 문제의식 <a class="header-anchor" href="#원효의-삶과-문제의식" aria-label="Permalink to &quot;원효의 삶과 문제의식&quot;">​</a></h2><p>신라의 삼국통일 시기에 활동. 10대에 출가해 여러 공부를 했으나 학문적 열정이 충족되지 않음. 30대에 유학을 가려다 고구려에서 문제가 생겨 가지 못했고, 40대에 당으로 가려던 도중 다시 문제가 생김.</p><p>유학길 도중 동굴에서 해골물을 마시고 동굴과 무덤이 둘이 아님을 깨닫고 유학을 포기함. 요석공주와 혼인해 설총을 낳고 대중교화에 힘쓰다, 다시 사원으로 돌아와 생을 마감함.</p><h2 id="원효의-일심·화쟁-사상" tabindex="-1">원효의 일심·화쟁 사상 <a class="header-anchor" href="#원효의-일심·화쟁-사상" aria-label="Permalink to &quot;원효의 일심·화쟁 사상&quot;">​</a></h2><p><strong>각(覺)의 문제</strong></p><blockquote><p>이 부분은 원본 강의노트가 여기서 끊겨 있어, 이후 내용(일심·화쟁 사상의 본론)은 비어 있음 — 추후 보강 필요.</p></blockquote>',11)])])}const u=o(l,[["render",i]]);export{d as __pageData,u as default};
